pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 ts) public {
        vm.assume(caller != address(0));
        ts = bound(ts, 1, type(uint64).max);

        vm.warp(ts);

        uint256 sendAmt = 10 ether;
        vm.deal(caller, sendAmt);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: sendAmt}("");
        require(ok, "fallback call failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
